import React, { useEffect, useState } from 'react';
import { adminGet, adminPost } from '../services/adminApi';
import { useNavigate } from 'react-router-dom';

export default function AdminDashboard() {
  const [payments, setPayments] = useState([]);
  const [users, setUsers] = useState([]);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  const adminUser = localStorage.getItem('admin_user');
  const adminPass = localStorage.getItem('admin_pass');
  useEffect(() => {
    if (!adminUser || !adminPass) return navigate('/admin');
    fetchPayments();
    fetchUsers();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [adminUser, adminPass]);

  async function fetchPayments() {
    try {
      const data = await adminGet('/admin/payments');
      setPayments(data || []);
    } catch (err) {
      setError(err.message || 'Failed to load');
    }
  }

  async function fetchUsers() {
    try {
      const data = await adminGet('/admin/users');
      setUsers(data || []);
    } catch (err) {
      setError(err.message || 'Failed to load users');
    }
  }

  async function approve(id) {
    try {
      await adminPost(`/admin/approve/${id}`);
      fetchPayments();
    } catch (err) {
      setError(err.message);
    }
  }

  async function reject(id) {
    try {
      await adminPost(`/admin/reject/${id}`);
      fetchPayments();
    } catch (err) {
      setError(err.message);
    }
  }

  function logout() {
    localStorage.removeItem('admin_user');
    localStorage.removeItem('admin_pass');
    localStorage.removeItem('admin_token');
    navigate('/admin');
  }

  async function banUser(id) {
    try {
      await adminPost(`/admin/user/${id}/ban`);
      fetchUsers();
    } catch (err) {
      setError(err.message);
    }
  }

  async function resendUser(id) {
    try {
      await adminPost(`/admin/user/${id}/resend`);
      alert('Verification resent');
    } catch (err) {
      setError(err.message);
    }
  }

  async function exportCsv() {
    try {
      const token = localStorage.getItem('admin_token');
      const headers = {};
      if (token) headers['Authorization'] = `Bearer ${token}`;
      else {
        const user = localStorage.getItem('admin_user');
        const pass = localStorage.getItem('admin_pass');
        const key = localStorage.getItem('admin_key');
        if (user && pass) { headers['x-admin-user'] = user; headers['x-admin-pass'] = pass; }
        else if (key) headers['x-admin-key'] = key;
      }
      const res = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/users/export`, { headers });
      const blob = await res.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'users.csv';
      document.body.appendChild(a);
      a.click();
      a.remove();
    } catch (err) {
      setError(err.message || 'Export failed');
    }
  }

  return (
    <div className="container" style={{ maxWidth: 900, margin: '24px auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <h2>Admin Dashboard</h2>
        <div>
          <button className="btn" onClick={logout}>Logout</button>
        </div>
      </div>

      {error && <div className="card">Error: {error}</div>}

      {payments.length === 0 && <div className="card">No pending payments</div>}

      <h3 style={{ marginTop: 16 }}>Registered Users</h3>
      {users.length === 0 && <div className="card">No users found</div>}
      <div style={{ marginTop: 8, marginBottom: 12 }}>
        <button className="btn" onClick={exportCsv}>Export CSV</button>
      </div>

      {users.map(u => (
        <div key={u.id} className="card" style={{ marginBottom: 8 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between' }}>
            <div>
              <strong>{u.email}</strong> {u.name ? `— ${u.name}` : ''}
              <div>Status: {u.accessStatus} — Verified: {u.isVerified ? 'yes' : 'no'}</div>
              <div>Joined: {new Date(u.createdAt).toLocaleString()}</div>
            </div>
            <div style={{ textAlign: 'right' }}>
              <button className="btn" onClick={() => banUser(u.id)} style={{ marginRight: 8 }}>Ban</button>
              {!u.isVerified && <button className="btn outline" onClick={() => resendUser(u.id)}>Resend</button>}
            </div>
          </div>
        </div>
      ))}

      {payments.map(p => (
        <div key={p.id} className="card" style={{ marginBottom: 12 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between' }}>
            <div>
              <strong>{p.user?.email}</strong> — {p.amount} — {p.status}
              <div>Txn: {p.transactionId}</div>
            </div>
            <div style={{ textAlign: 'right' }}>
              {p.screenshotUrl && <a href={p.screenshotUrl} target="_blank" rel="noreferrer">View screenshot</a>}
              <div style={{ marginTop: 8 }}>
                <button className="btn" onClick={() => approve(p.id)} style={{ marginRight: 8 }}>Approve</button>
                <button className="btn outline" onClick={() => reject(p.id)}>Reject</button>
              </div>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}
